429	+    {
430	+        var veranstaltung = await db.Veranstaltungen
431	+            .Include(v => v.Raum)
432	+            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
433	+
434	+        if (veranstaltung is null)
435	+        {
436	+            return null;
437	+        }
438	+
439	+        var raum = veranstaltung.Raum!;
440	+
441	+        var belegteCodes = (await db.Sitzplatzbelegungen
442	+            .Where(s => s.VeranstaltungId == veranstaltungId)
443	+            .Select(s => s.SitzplatzCode)
444	+            .ToListAsync())
445	+            .ToHashSet();
446	+
447	+        var reihen = raum.Reihen.Select(reihe =>
448	+        {
449	+            var positionen = new List<SitzplanPositionDto>();
450	+            for (var spalte = 1; spalte <= raum.Spalten; spalte++)
451	+            {
452	+                if (raum.GangSpalten.Contains(spalte))
453	+                {
454	+                    positionen.Add(new SitzplanPositionDto(spalte, "Gang", null, null));
